import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Part","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/part.md","filePath":"03-developer/models/part.md"}`),a={name:`03-developer/models/part.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="part" tabindex="-1">Part <a class="header-anchor" href="#part" aria-label="Permalink to “Part”">​</a></h1><p>The <code>Part</code> model is used to store settings and references to reusable components in the site&#39;s theming system. Each record specifies which Theme Part should be loaded from which Segment and in what order. It can also be associated with an <code>Area</code> or assigned a custom Theme for a specific entity.</p><p>In this architecture, <strong>Segment specifies the type or placement of a theme component, while Part specifies which implementation of that component to use.</strong></p><h2 id="parts-table-structure" tabindex="-1"><code>parts</code> table structure <a class="header-anchor" href="#parts-table-structure" aria-label="Permalink to “parts table structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Record ID</td></tr><tr><td><code>area_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>ID of the associated Area, if any</td></tr><tr><td><code>segment</code></td><td>VARCHAR(255)</td><td>No</td><td>Segment name, such as <code>footer</code> or <code>menu</code></td></tr><tr><td><code>part</code></td><td>VARCHAR(255)</td><td>No</td><td>Name of the Theme Part to use, such as <code>AplMenu</code> or <code>WaveFooter</code></td></tr><tr><td><code>data</code></td><td>LONGTEXT</td><td>No</td><td>Additional JSON data associated with the Part; defaults to an empty JSON array</td></tr><tr><td><code>sort</code></td><td>INT</td><td>No</td><td>Order in which the Part is displayed or loaded; defaults to <code>0</code></td></tr><tr><td><code>custom</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Identifies a custom Theme associated with a specific entity</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update time</td></tr></tbody></table><h2 id="the-concepts-of-segment-and-part" tabindex="-1">The concepts of Segment and Part <a class="header-anchor" href="#the-concepts-of-segment-and-part" aria-label="Permalink to “The concepts of Segment and Part”">​</a></h2><h3 id="segment" tabindex="-1"><code>segment</code> <a class="header-anchor" href="#segment" aria-label="Permalink to “segment”">​</a></h3><p>The Segment name specifies the category or Segment path from which the theme component is selected. For example:</p><ul><li><code>menu</code></li><li><code>footer</code></li></ul><p>This value corresponds to the Segment directory structure in the theming system.</p><h3 id="part-1" tabindex="-1"><code>part</code> <a class="header-anchor" href="#part-1" aria-label="Permalink to “part”">​</a></h3><p>Specifies which implementation of a Segment to use. For example:</p><ul><li><code>AplMenu</code> for a menu</li><li><code>WaveFooter</code> for a footer</li></ul><p>As a result, multiple Theme Parts can exist for a single Segment, and the value of <code>part</code> determines which one is used.</p><h2 id="custom-theme-for-entities" tabindex="-1">Custom Theme for entities <a class="header-anchor" href="#custom-theme-for-entities" aria-label="Permalink to “Custom Theme for entities”">​</a></h2><h3 id="custom" tabindex="-1"><code>custom</code> <a class="header-anchor" href="#custom" aria-label="Permalink to “custom”">​</a></h3><p>This field is used to specify a custom Theme for a specific entity; for example, assigning a dedicated Landing Page to a group or another entity.</p><p>In this case, Part settings can be associated with that entity&#39;s custom Theme instead of relying solely on the site&#39;s general settings.</p><p>This capability makes it possible to create a custom appearance for an entity. How this Theme is identified and loaded depends on the theming system&#39;s implementation logic.</p><h2 id="additional-data" tabindex="-1">Additional data <a class="header-anchor" href="#additional-data" aria-label="Permalink to “Additional data”">​</a></h2><h3 id="data" tabindex="-1"><code>data</code> <a class="header-anchor" href="#data" aria-label="Permalink to “data”">​</a></h3><p>The <code>data</code> field is intended to store additional JSON data associated with the Part. It can hold information required when registering or loading the Theme Part.</p><p>So far, according to the project description, this field has not been used in practice. However, it could be used in the future for capabilities such as storing additional data or information related to updating the preview image.</p><h3 id="sort" tabindex="-1"><code>sort</code> <a class="header-anchor" href="#sort" aria-label="Permalink to “sort”">​</a></h3><p>Specifies the order in which Parts are placed. This field makes it possible to determine the order in which theme components are used.</p><h2 id="database-notes" tabindex="-1">Database notes <a class="header-anchor" href="#database-notes" aria-label="Permalink to “Database notes”">​</a></h2><ul><li>The <code>data</code> field has a <code>CHECK (json_valid(data))</code> constraint; therefore, the stored value must be valid JSON.</li><li>The <code>area_id</code> field has no foreign key in the provided SQL; its relationship with <code>Area</code> is not enforced by this database definition.</li><li>The <code>custom</code> field is nullable; therefore, not all Parts are necessarily associated with a custom Theme.</li><li>The table does not define a uniqueness constraint for the combination of <code>area_id</code>, <code>segment</code>, <code>part</code>, and <code>custom</code>; therefore, the uniqueness of such a combination cannot be inferred from the SQL structure.</li></ul><h2 id="methods-and-relationships" tabindex="-1">Methods and relationships <a class="header-anchor" href="#methods-and-relationships" aria-label="Permalink to “Methods and relationships”">​</a></h2><h3 id="getbladewithdata-item-null" tabindex="-1"><code>getBladeWithData($item = null)</code> <a class="header-anchor" href="#getbladewithdata-item-null" aria-label="Permalink to “getBladeWithData($item = null)”">​</a></h3><p>This method returns the Blade template path and the data required to render the Theme Part.</p><p>It first constructs the class for the Part using the value of <code>part</code>, then calls the static <code>onMount()</code> method on that class. The result is returned as an array with two keys:</p><ul><li><code>blade</code>: The template path, in the form <code>segments.{segment}.{part}.{part}</code></li><li><code>data</code>: The data returned by the <code>onMount()</code> method.</li></ul><p>The <code>$item</code> parameter is optional and is used when preparing the Part&#39;s data depends on the current page entity.</p><p>For example, a footer Part might prepare its required data without receiving an external entity. By contrast, a product grid or gallery image Part can receive the current entity to prepare the appropriate data for display.</p><h3 id="getblade" tabindex="-1"><code>getBlade()</code> <a class="header-anchor" href="#getblade" aria-label="Permalink to “getBlade()”">​</a></h3><p>This method constructs the class for the Part using the value of <code>part</code>, calls the static <code>onMount($this)</code> method, and returns the Blade path in the form <code>segments.{segment}.{part}.{part}</code>.</p><p>Unlike <code>getBladeWithData()</code>, this method does not include the <code>onMount()</code> result in its return value.</p><h3 id="area" tabindex="-1"><code>area()</code> <a class="header-anchor" href="#area" aria-label="Permalink to “area()”">​</a></h3><p>Establishes a <code>belongsTo</code> relationship with the <a href="./area.html">Area</a> model and returns the Area associated with this Part.</p><h3 id="getareanameattribute" tabindex="-1"><code>getAreaNameAttribute()</code> <a class="header-anchor" href="#getareanameattribute" aria-label="Permalink to “getAreaNameAttribute()”">​</a></h3><p>Provides the computed <code>area_name</code> attribute:</p><ul><li>If <code>area_id</code> has a value, returns the name of the associated Area through <code>$this-&gt;area-&gt;name</code>.</li><li>Otherwise, returns the value of the <code>custom</code> field.</li></ul><h2 id="usage-in-a-blade-template" tabindex="-1">Usage in a Blade template <a class="header-anchor" href="#usage-in-a-blade-template" aria-label="Permalink to “Usage in a Blade template”">​</a></h2><p>When rendering Parts, <code>getBladeWithData()</code> is first called, and the resulting template path and data are then passed to <code>@include</code>:</p><div class="language-php"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($p </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $part</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBladeWithData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($gallery))</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($p[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;blade&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;data&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $p[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;data&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]])</span></span></code></pre></div><p>In this example, the <code>$gallery</code> entity is passed to the Part so that, if needed, <code>onMount()</code> can prepare data associated with it.</p><p>For Parts that do not depend on the current entity, the parameter is omitted:</p><div class="language-php"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($p </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $part</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBladeWithData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($p[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;blade&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;data&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $p[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;data&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]])</span></span></code></pre></div><p>This pattern is also used for general components, such as the default header and footer.</p><p><strong>Architectural note:</strong> Each Theme Part can have its own appearance and internal settings and, if needed, can also receive data related to the current entity. This separates the theme component&#39;s appearance logic from the content data it displays.</p>`,50)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};